enum ServoSkullRole { scout, medic, hunter, suppressor }
class ServoSkullState { final ServoSkullRole role; final int level; double cooldown; ServoSkullState({required this.role, this.level=1, this.cooldown=0}); }
class ServoSkullSystem { final List<ServoSkullState> companions=[]; void add(ServoSkullRole role,{int level=1}){if(companions.any((c)=>c.role==role))return;companions.add(ServoSkullState(role:role,level:level.clamp(1,5).toInt()));} Map<String,double> update(double dt){final effects=<String,double>{};for(final c in companions){c.cooldown=_maxDouble(0,c.cooldown-dt);if(c.cooldown>0)continue;switch(c.role){case ServoSkullRole.scout:effects['revealRadius']=(effects['revealRadius']??0)+90*c.level;c.cooldown=2.0;break;case ServoSkullRole.medic:effects['heal']=(effects['heal']??0)+c.level.toDouble();c.cooldown=5.0;break;case ServoSkullRole.hunter:effects['damage']=(effects['damage']??0)+c.level.toDouble();c.cooldown=1.5;break;case ServoSkullRole.suppressor:effects['slow']=(effects['slow']??0)+.2*c.level;c.cooldown=3.0;break;}}return effects;} Map<String,dynamic> toJson()=>{'companions':companions.map((c)=>{'role':c.role.name,'level':c.level,'cooldown':c.cooldown}).toList()}; void loadJson(dynamic raw){if(raw is! Map||raw['companions'] is! List)return;companions.clear();for(final entry in raw['companions'] as List){if(entry is! Map||entry['role'] is! String)continue;final role=ServoSkullRole.values.where((e)=>e.name==entry['role']).firstOrNull;if(role==null)continue;companions.add(ServoSkullState(role:role,level:entry['level'] is num?(entry['level'] as num).toInt().clamp(1,5).toInt():1,cooldown:entry['cooldown'] is num?(entry['cooldown'] as num).toDouble().clamp(0,60).toDouble():0));}} double _maxDouble(double a,double b)=>a>b?a:b; }

extension _ServoFirstOrNull<T> on Iterable<T>{T? get firstOrNull=>isEmpty?null:first;}
